(7295419, 1137602, 30490, '<td valign="top">Great idea and nice execution!</td>', 'Great idea and nice execution!', '2014-12-24 13:11:22.000000', NULL, 1),
(7295420, 1137705, 30490, '<td valign="top">I like the old fashioned looking color desat and vingette on this image.</td>', 'I like the old fashioned looking color desat and vingette on this image.', '2014-12-24 13:12:18.000000', NULL, 1),
