(7295423, 1137560, 30490, '<td valign="top">Nice close up portrait, great skin tones and love the color of the bubble gum!</td>', 'Nice close up portrait, great skin tones and love the color of the bubble gum!', '2014-12-24 13:14:18.000000', NULL, 1),
