(7296973, 1137688, 13077, '<td valign="top">Cute and colorful. Could probably have done with a bit more sharpening, though.</td>', 'Cute and colorful. Could probably have done with a bit more sharpening, though.', '2014-12-30 20:41:16.000000', NULL, 1),
(7296974, 1137712, 13077, '<td valign="top">Great job on the windblown hair and the punchy colors. I see a spot of lens/sensor dust up by the top of her head, though.</td>', 'Great job on the windblown hair and the punchy colors. I see a spot of lens/sensor dust up by the top of her head, though.', '2014-12-30 20:42:06.000000', NULL, 1),
(7296976, 1137673, 13077, '<td valign="top">The lighting looks pretty good (maybe a little harder than normal for a portrait of a lady), but the focus wasn''t quite on for the eyes which are the first thing the viewers eyes tend to jump to.</td>', 'The lighting looks pretty good (maybe a little harder than normal for a portrait of a lady), but the focus wasn''t quite on for the eyes which are the first thing the viewers eyes tend to jump to.', '2014-12-30 20:43:34.000000', NULL, 1),
(7296977, 1137703, 13077, '<td valign="top">Yeah, I give up on those too. Cool window, though, looks familiar.</td>', 'Yeah, I give up on those too. Cool window, though, looks familiar.', '2014-12-30 20:44:03.000000', NULL, 1),
(7296979, 1137695, 13077, '<td valign="top">Sure would have been cool if he had blown a big bubble and you had the sun right behind it.</td>', 'Sure would have been cool if he had blown a big bubble and you had the sun right behind it.', '2014-12-30 20:45:17.000000', NULL, 1),
